export const legacyRoutes = { '/': 'HOME-01', '/index.html': 'SIM-01', '/simulate.html': 'EX-01', '/scenarios.html': 'CAT-01', '/analytics.html': 'ANA-01', '/team.html': 'PEO-01', '/library.html': 'REP-01', '/risks.html': 'ACT-01', '/settings.html': 'SET-01', '/screen-2.html': 'EX-02', '/screen-3.html': 'SIM-01', '/screen-4.html': 'SIM-05', '/screen-5.html': 'SIM-06', '/screen-6.html': 'REV-01' };
