export function routeTo(id, params = {}, query = {}) {
    const s = screens.find(s => s.id === id);
    if (!s)
        return '/unavailable';
    if (id === 'EX-02' && query.edit === 'yes' && params.exerciseId) {
        const search = new URLSearchParams(query).toString();
        return `/o/${encodeURIComponent(params.orgSlug || 'atlas')}/exercises/${encodeURIComponent(params.exerciseId)}/edit?${search}`;
    }
    const path = s.route.replace(/:([A-Za-z]+)/g, (_, key) => encodeURIComponent(params[key] || defaultIds[key] || 'unavailable'));
    const search = new URLSearchParams(query).toString();
    return path + (search ? '?' + search : '');
}
export function matchRoute(path) {
    const edit = path.match(/^\/o\/([^/]+)\/exercises\/([^/]+)\/edit\/?$/);
    if (edit)
        return { screen: screens.find(s => s.id === 'EX-02'), params: { orgSlug: decodeURIComponent(edit[1]), exerciseId: decodeURIComponent(edit[2]) } };
    const imported = path.match(/^\/o\/([^/]+)\/scenario-imports\/([^/]+)\/?$/);
    if (imported && imported[2] !== 'new')
        return { screen: screens.find(s => s.id === 'PKG-01'), params: { orgSlug: decodeURIComponent(imported[1]), importId: decodeURIComponent(imported[2]) } };
    const alias = legacyRoutes[path];
    if (alias)
        return { screen: screens.find(s => s.id === alias), params: { ...defaultIds } };
    for (const screen of [...screens].sort((a, b) => b.route.split('/').length - a.route.split('/').length || a.route.includes(':').toString().localeCompare(b.route.includes(':').toString()))) {
        const keys = [];
        const re = new RegExp('^' + screen.route.replace(/:([A-Za-z]+)/g, (_, key) => { keys.push(key); return '([^/]+)'; }) + '/?$');
        const m = path.match(re);
        if (m)
            return { screen, params: Object.fromEntries(keys.map((key, i) => [key, decodeURIComponent(m[i + 1])])) };
    }
    return null;
}
